36	bool MatmulParamCheck(const infer::LinearParam &opParam, ExternalError &error)
37	{
38	    if (opParam.quantMode != atb::infer::LinearParam::QUANT_UNDEFINED) {
39	        error.errorData = OperationUtil::ConcatInfo(error.errorData, "quantMode = ", opParam.quantMode);
40	        error.errorDesc = "QuantMode is not the default value. When outDataType is undefind, quantMode needs to be undefind.";
41	        error.solutionDesc = "Please check the quantMode value of input params.";
42	        ATB_LOG(ERROR) << error;
43	        return false;
44	    }
45	    if (opParam.enAccum) {
46	        error.errorData = OperationUtil::ConcatInfo(error.errorData, "enAccum = ", opParam.enAccum);
47	        if (!GetSingleton<Config>().Is910B()) {
48	            error.errorDesc = "Platform is not Atlas 800I A2 inference product, enAccum should be false,";
49	            error.solutionDesc = "Please check the platform and value of input params.";
50	            ATB_LOG(ERROR) << error;
51	            return false;
52	        }
53	        if (opParam.hasBias) {
54	            error.errorDesc = "enAccum and hasBias can not both be true!";
55	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", hasBias = ", opParam.hasBias);
56	            ATB_LOG(ERROR) << error;
57	            return false;
58	        }
59	    }
60	    return true;
61	}
