63	bool MatmulEinParamCheck(const infer::LinearParam &opParam, ExternalError &error)
64	{
65	    if (opParam.enAccum) {
66	        error.errorDesc = "When MatmulEin is used, enAccum should be false,";
67	        error.solutionDesc = "Please check the value of input params.";
68	        ATB_LOG(ERROR) << error;
69	        return false;
70	    } else if (opParam.transposeA) {
71	        error.errorDesc = "When MatmulEin is used, transposeA should be false,";
72	        error.solutionDesc = "Please check the value of input params.";
73	        ATB_LOG(ERROR) << error;
74	        return false;
75	    } else if (opParam.hasBias) {
76	        error.errorDesc = "When MatmulEin is used, hasBias should be false,";
77	        error.solutionDesc = "Please check the value of input params.";
78	        ATB_LOG(ERROR) << error;
79	        return false;
80	    } else if (opParam.outDataType != ACL_DT_UNDEFINED) {
81	        error.errorDesc = "When MatmulEin is used, outDataType should be ACL_DT_UNDEFINED,";
82	        error.solutionDesc = "Please check the value of input params.";
83	        ATB_LOG(ERROR) << error;
84	        return false;
85	    }
86	    return true;
87	}
