89	bool MatmulDequantFloat16ParamCheck(const infer::LinearParam &opParam, ExternalError &error)
90	{
91	    if (!GetSingleton<Config>().Is910B()) {
92	        error.errorDesc = "Platform is not Atlas 800I A2 inference product, outDataType is ACL_FLOAT16, ";
93	        error.solutionDesc = "Please check the platform and value of input params.";
94	        if (opParam.transposeA) {
95	            error.errorDesc = error.errorDesc + "transposeA should be false.";
96	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", transposeA = ", opParam.transposeA);
97	            ATB_LOG(ERROR) << error;
98	            return false;
99	        }
100	        if (!opParam.transposeB) {
101	            error.errorDesc = error.errorDesc + "transposeB should be true.";
102	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", transposeB = ", opParam.transposeB);
103	            ATB_LOG(ERROR) << error;
104	            return false;
105	        }
106	        if (!opParam.hasBias && !GetSingleton<Config>().Is310B()) {
107	            error.errorDesc = error.errorDesc + "hasBias should be true.";
108	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", hasBias = ", opParam.hasBias);
109	            ATB_LOG(ERROR) << error;
110	            return false;
111	        }
112	        if (opParam.quantMode == infer::LinearParam::PER_TOKEN) {
113	            error.errorDesc = error.errorDesc + "quantMode should be QUANT_UNDEFINED or PER_CHANNEL.";
114	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", quantMode = ", opParam.quantMode);
115	            ATB_LOG(ERROR) << error;
116	            return false;
117	        }
118	    } else if (opParam.quantMode == infer::LinearParam::PER_TOKEN && opParam.hasBias) {
119	        error.errorDesc = "PER_TOKEN quantMode is not supported when hasBias is true";
120	        error.solutionDesc = "Please check the value of input params.";
121	        ATB_LOG(ERROR) << error;
122	        return false;
123	    }
124	    return true;
125	}
