144	bool MatmulUndefindCheck(const infer::LinearParam &opParam, ExternalError &error)
145	{
146	    switch (opParam.outDataType) {
147	        case ACL_DT_UNDEFINED:
148	            {
149	                if (!MatmulParamCheck(opParam, error)) {
150	                    return false;
151	                }
152	                break;
153	            }
154	        case ACL_FLOAT16:
155	            {
156	                if (opParam.enAccum) {
157	                    error.errorDesc = "outDataType is not ACL_DT_UNDEFINED, enAccum should be false.";
158	                    error.errorData = OperationUtil::ConcatInfo(error.errorData, ", enAccum = ", opParam.enAccum);
159	                    ATB_LOG(ERROR) << error;
160	                    return false;
161	                }
162	                if (!MatmulDequantFloat16ParamCheck(opParam, error)) {
163	                    return false;
164	                }
165	                break;
166	            }
167	        case ACL_BF16:
168	            {
169	                if (opParam.enAccum) {
170	                    error.errorDesc = "outDataType is not ACL_DT_UNDEFINED, enAccum should be false.";
171	                    error.errorData = OperationUtil::ConcatInfo(error.errorData, ", enAccum = ", opParam.enAccum);
172	                    ATB_LOG(ERROR) << error;
173	                    return false;
174	                }
175	                if (!MatmulDequantBf16ParamCheck(opParam, error)) {
176	                    return false;
177	                }
178	                break;
179	            }
180	        default:
181	            {
182	                error.errorDesc = "outDataType should be ACL_DT_UNDEFINED/ACL_FLOAT16/ACL_BF16.";
183	                ATB_LOG(ERROR) << error;
184	                return false;
185	            }
186	    }
187	    return true;
188	}
