224	template <> Status CreateOperation(const infer::LinearParam &opParam, Operation **operation)
225	{
226	    if (operation == nullptr) {
227	        return ERROR_INVALID_PARAM;
228	    }
229	    OP_PARAM_RSV_CHECK(opParam);
230	
231	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
232	        if (LinearAclnnRunner::LoadAclnnFuncs() != NO_ERROR) {
233	            ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
234	            return ERROR_CANN_ERROR;
235	        }
236	        if (LinearEinsumAclnnRunner::LoadAclnnFuncs() != NO_ERROR) {
237	            ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
238	            return ERROR_CANN_ERROR;
239	        }
240	        if (LinearDequantAclnnRunner::LoadAclnnFuncs() != NO_ERROR) {
241	            ATB_LOG(ERROR) << "Load dequant aclnn function failed, please check your CANN version.";
242	            return ERROR_CANN_ERROR;
243	        }
244	
245	        ExternalError error;
246	        error.errorType = ERROR_INVALID_PARAM;
247	        error.errorData = OperationUtil::ConcatInfo("outDataType = ", opParam.outDataType);
248	        error.solutionDesc = "Please check the value of input params.";
249	
250	        if (opParam.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
251	            if (!MatmulEinParamCheck(opParam, error)) {
252	                return ERROR_INVALID_PARAM;
253	            }
254	        } else if (opParam.matmulType == infer::LinearParam::MATMUL_UNDEFINED) {
255	            if (!MatmulUndefindCheck950(opParam, error)) {
256	                return ERROR_INVALID_PARAM;
257	            }
258	        } else {
259	            error.errorDesc = "matmulType uses an nonexistent type.";
260	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", matmulType = ", opParam.matmulType);
261	            ATB_LOG(ERROR) << error;
262	            return ERROR_INVALID_PARAM;
263	        }
264	
265	        *operation = new (std::nothrow) LinearOperation(opParam);
266	        if (*operation == nullptr) {
267	            ATB_LOG(ERROR) << "failed to new operation";
268	            return ERROR_OUT_OF_HOST_MEMORY;
269	        }
270	        return NO_ERROR;
271	    }
272	
273	    ExternalError error;
274	    error.errorType = ERROR_INVALID_PARAM;
275	    error.errorData = OperationUtil::ConcatInfo("outDataType = ", opParam.outDataType);
276	    error.solutionDesc = "Please check the value of input params.";
277	    if (opParam.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
278	        if (!MatmulEinParamCheck(opParam, error)) {
279	            return ERROR_INVALID_PARAM;
280	        }
281	        if (!GetSingleton<Config>().Is910B()) {
282	            error.errorDesc = "Platform is not Atlas 800I A2 inference product, MatmulType should be 0,";
283	            error.solutionDesc = "Please check the platform and value of input params.";
284	            ATB_LOG(ERROR) << error;
285	            return ERROR_INVALID_PARAM;
286	        }
287	    } else if (opParam.matmulType == infer::LinearParam::MATMUL_UNDEFINED) {
288	        if (!MatmulUndefindCheck(opParam, error)) {
289	            return ERROR_INVALID_PARAM;
290	        }
291	    } else {
292	        error.errorDesc = "matmulType uses an nonexistent type.";
293	        error.errorData = OperationUtil::ConcatInfo(error.errorData, ", matmulType = ", opParam.matmulType);
294	
295	        ATB_LOG(ERROR) << error;
296	        return ERROR_INVALID_PARAM;
297	    }
298	
299	    *operation = new (std::nothrow) LinearOperation(opParam);
300	    if (*operation == nullptr) {
301	        ATB_LOG(ERROR) << "failed to new operation";
302	        return ERROR_OUT_OF_HOST_MEMORY;
303	    }
304	    return NO_ERROR;
305	}
