365	uint32_t LinearOperation::GetInputNum() const
366	{
367	    if (param_.outDataType == ACL_DT_UNDEFINED) {
368	        if (param_.hasBias || param_.enAccum) {
369	            return IN_TENSOR_NUM_3;
370	        } else {
371	            return IN_TENSOR_NUM_2;
372	        }
373	    } else {
374	        if (param_.hasBias) {
375	            return IN_TENSOR_NUM_4;
376	        } else if (param_.quantMode == infer::LinearParam::PER_TOKEN) {
377	            return IN_TENSOR_NUM_4;
378	        } else {
379	            return IN_TENSOR_NUM_3;
380	        }
381	    }
382	}
