389	Status LinearOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
390	                                       SVector<TensorDesc> &outTensorDescs) const
391	{
392	    outTensorDescs.at(0) = inTensorDescs.at(0);
393	    if (param_.outDataType == ACL_DT_UNDEFINED) {
394	        if (param_.enAccum) {
395	            outTensorDescs.at(0).dtype = ACL_FLOAT;
396	        }
397	    } else {
398	        outTensorDescs.at(0).dtype = param_.outDataType;
399	    }
400	    int64_t m = OperationUtil::GetXTensorM(inTensorDescs.at(0), param_.transposeA, param_.matmulType);
401	    int64_t n = OperationUtil::GetYTensorN(inTensorDescs.at(1), param_.transposeB);
402	    uint64_t xDimNum = inTensorDescs.at(0).shape.dimNum;
403	    outTensorDescs.at(0).shape.dims[xDimNum - DIM_2] = m;
404	    outTensorDescs.at(0).shape.dims[xDimNum - 1] = n;
405	    if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
406	        outTensorDescs.at(0).shape.dims[0] =
407	            param_.transposeA ? inTensorDescs.at(0).shape.dims[DIM_2] : inTensorDescs.at(0).shape.dims[0];
408	        outTensorDescs.at(0).shape.dims[1] = inTensorDescs.at(0).shape.dims[1];
409	        outTensorDescs.at(0).shape.dims[DIM_2] = n;
410	    }
411	    return NO_ERROR;
412	}
