430	std::shared_ptr<Runner> LinearOperation::CreateRunner(Context &context) const
431	{
432	    (void)context;
433	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
434	        if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
435	            return std::make_shared<LinearEinsumAclnnRunner>(param_);
436	        }
437	        if (param_.outDataType != ACL_DT_UNDEFINED) {
438	            return std::make_shared<LinearDequantAclnnRunner>(param_);
439	        }
440	        return std::make_shared<LinearAclnnRunner>(param_);
441	    }
442	    return std::make_shared<LinearOpsRunner>(param_);
443	}
