450	Status LinearOperation::InTensorDescsCheck(const SVector<TensorDesc> &inTensorDescs) const
451	{
452	    size_t inTensorId = 0;
453	    const TensorDesc &xTensorDesc = inTensorDescs.at(inTensorId++);
454	    const TensorDesc &weightTensorDesc = inTensorDescs.at(inTensorId++);
455	    if (GetSingleton<Config>().Is310B() && xTensorDesc.dtype == aclDataType::ACL_FLOAT16 && param_.transposeA) {
456	        ATB_LOG(ERROR) << "Atlas 200I/500 A2 inference product does not support transposeA=true!";
457	        return ERROR_INVALID_PARAM;
458	    }
459	    Status status = NO_ERROR;
460	    if (param_.outDataType == ACL_DT_UNDEFINED) {
461	        status = XWeightCheck(xTensorDesc, weightTensorDesc, DEFAULT_ALIGN);
462	        if (status != NO_ERROR) {
463	            return status;
464	        }
465	        if (param_.hasBias) {
466	            const TensorDesc &biasTensorDesc = inTensorDescs.at(inTensorId++);
467	            status = BiasCheck(biasTensorDesc, weightTensorDesc);
468	            if (status != NO_ERROR) {
469	                return status;
470	            }
471	        } else if (param_.enAccum) {
472	            const TensorDesc &accumTensorDesc = inTensorDescs.at(inTensorId++);
473	            status = AccumCheck(accumTensorDesc, xTensorDesc, weightTensorDesc);
474	            if (status != NO_ERROR) {
475	                return status;
476	            }
477	        }
478	    } else {
479	        status = XWeightCheck(xTensorDesc, weightTensorDesc, INT8_ALIGN);
480	        if (status != NO_ERROR) {
481	            return status;
482	        }
483	        if (param_.hasBias) {
484	            const TensorDesc &biasTensorDesc = inTensorDescs.at(inTensorId++);
485	            status = BiasCheck(biasTensorDesc, weightTensorDesc);
486	            if (status != NO_ERROR) {
487	                return status;
488	            }
489	        }
490	        const TensorDesc &deqScaleTensorDesc = inTensorDescs.at(inTensorId++);
491	        if (param_.quantMode == infer::LinearParam::PER_TOKEN) {
492	            const TensorDesc &perTokenDeqScaleTensorDesc = inTensorDescs.at(inTensorId++);
493	            status = PerTokenDeqScaleCheck(deqScaleTensorDesc, weightTensorDesc, xTensorDesc, perTokenDeqScaleTensorDesc);
494	        } else {
495	            status = DeqScaleCheck(deqScaleTensorDesc, weightTensorDesc);
496	        }
497	        if (status != NO_ERROR) {
498	            return status;
499	        }
500	    }
501	    return NO_ERROR;
502	}
