504	Status LinearOperation::XWeightCheck(const TensorDesc &xTensorDesc, const TensorDesc &weightTensorDesc,
505	                                     int64_t align) const
506	{
507	    if (!XWeightDimNumCheck(xTensorDesc, weightTensorDesc)) {
508	        return ERROR_INVALID_TENSOR_DIM_NUM;
509	    }
510	    if (!XWeightBatchCheck(xTensorDesc, weightTensorDesc)) {
511	        return ERROR_INVALID_TENSOR_DIM;
512	    }
513	    if (!XWeightKEqualCheck(xTensorDesc, weightTensorDesc)) {
514	        return ERROR_INVALID_TENSOR_DIM;
515	    }
516	    if (!WeightAlignCheck(weightTensorDesc, align)) {
517	        return ERROR_INVALID_TENSOR_DIM;
518	    }
519	    return NO_ERROR;
520	}
