561	{
562	    ExternalError error;
563	    error.errorType = ERROR_INVALID_TENSOR_DIM;
564	    error.solutionDesc = "Please check shape of inTensors";
565	
566	    if (accumTensorDesc.shape.dimNum != xTensorDesc.shape.dimNum) {
567	        error.errorType = ERROR_INVALID_TENSOR_DIM_NUM;
568	        error.errorDesc = "inTensor2 dim num and inTensor0 dim num should be equal,";
569	        error.errorData = OperationUtil::ConcatInfo("inTensor2 dimNum = ", accumTensorDesc.shape.dimNum,
570	                                                    ", inTensor0 dimNum = ", xTensorDesc.shape.dimNum);
571	        ATB_LOG(ERROR) << GetLogPrefix() << error;
572	        return error.errorType;
573	    }
574	    int64_t accumBatch = OperationUtil::GetTensorBatch(accumTensorDesc, param_.matmulType);
575	    int64_t xBatch = OperationUtil::GetTensorBatch(xTensorDesc, param_.matmulType);
576	    if (accumBatch != xBatch) {
577	        error.errorDesc = "value of inTensor2 batch and inTensor0 batch should be equal,";
578	        error.errorData = OperationUtil::ConcatInfo("inTensor2 batch = ", accumBatch, ", inTensor0 batch = ", xBatch);
579	        ATB_LOG(ERROR) << GetLogPrefix() << error;
580	        return error.errorType;
581	    }
582	    int64_t accumM = accumTensorDesc.shape.dims[accumTensorDesc.shape.dimNum - DIM_2];
583	    int64_t xM = OperationUtil::GetXTensorM(xTensorDesc, param_.transposeA, param_.matmulType);
584	    if (accumM != xM) {
585	        error.errorDesc = "value of inTensor2 m and inTensor0 m should be equal,";
586	        error.errorData = OperationUtil::ConcatInfo("inTensor2 m = ", accumM, ", inTensor0 m = ", xM);
587	        ATB_LOG(ERROR) << GetLogPrefix() << error;
588	        return error.errorType;
589	    }
590	    int64_t accumN = accumTensorDesc.shape.dims[accumTensorDesc.shape.dimNum - 1];
591	    int64_t weightN = OperationUtil::GetYTensorN(weightTensorDesc, param_.transposeB);
592	    if (accumN != weightN) {
593	        error.errorDesc = "value of inTensor2 n and inTensor1 n should be equal,";
594	        error.errorData = OperationUtil::ConcatInfo("inTensor2 n = ", accumN, ", inTensor1 n = ", weightN);
595	        ATB_LOG(ERROR) << GetLogPrefix() << error;
596	        return error.errorType;
597	    }
598	    return NO_ERROR;
599	}
