670	Status LinearOperation::OutTensorCheck(const SVector<TensorDesc> &inTensorDescs,
671	                                       const SVector<Tensor> &outTensors) const
672	{
673	    const TensorDesc &xTensorDesc = inTensorDescs.at(0);
674	    const TensorDesc &weightTensorDesc = inTensorDescs.at(1);
675	    const TensorDesc &outTensorDesc = outTensors.at(0).desc;
676	    ExternalError error;
677	    if (outTensorDesc.shape.dimNum != xTensorDesc.shape.dimNum) {
678	        error.errorType = ERROR_INVALID_TENSOR_DIM_NUM;
679	        error.errorDesc = "outTensor dimNum and inTensor0 dimNum should be equal,";
680	        error.errorData = OperationUtil::ConcatInfo("outTensor dimNum = ", outTensorDesc.shape.dimNum,
681	                                                    ", inTensor0 dimNum = ", xTensorDesc.shape.dimNum);
682	        error.solutionDesc = "Please check shape of outTensor.";
683	        ATB_LOG(ERROR) << GetLogPrefix() << error;
684	        return error.errorType;
685	    }
686	    int64_t outBatch = OperationUtil::GetTensorBatch(outTensorDesc, param_.matmulType);
687	    int64_t xBatch = OperationUtil::GetTensorBatch(xTensorDesc, param_.matmulType);
688	    if (outBatch != xBatch) {
689	        error.errorType = ERROR_INVALID_TENSOR_DIM;
690	        error.errorDesc = "value of outTensor batch and inTensor0 batch should be equal,";
691	        error.errorData = OperationUtil::ConcatInfo("outTensor batch = ", outBatch, ", inTensor0 batch = ", xBatch);
692	        error.solutionDesc = "Please check shape of outTensor.";
693	        ATB_LOG(ERROR) << GetLogPrefix() << error;
694	        return error.errorType;
695	    }
696	    int64_t outM = OperationUtil::GetOutTensorM(outTensorDesc, param_.matmulType);
697	    int64_t xM = OperationUtil::GetXTensorM(xTensorDesc, param_.transposeA, param_.matmulType);
698	    if (outM != xM) {
699	        error.errorType = ERROR_INVALID_TENSOR_DIM;
700	        error.errorDesc = "value of outTensor m and inTensor0 m should be equal,";
701	        error.errorData = OperationUtil::ConcatInfo("outTensor m = ", outM, ", inTensor0 m = ", xM);
702	        error.solutionDesc = "Please check shape of outTensor.";
703	        ATB_LOG(ERROR) << GetLogPrefix() << error;
704	        return error.errorType;
705	    }
706	    int64_t outN = OperationUtil::GetOutTensorN(outTensorDesc);
707	    int64_t weightN = OperationUtil::GetYTensorN(weightTensorDesc, param_.transposeB);
708	    if (outN != weightN) {
709	        error.errorType = ERROR_INVALID_TENSOR_DIM;
710	        error.errorDesc = "value of outTensor n and inTensor1 n should be equal,";
711	        error.errorData = OperationUtil::ConcatInfo("outTensor n = ", outN, ", inTensor1 n = ", weightN);
712	        error.solutionDesc = "Please check shape of outTensor.";
713	        ATB_LOG(ERROR) << GetLogPrefix() << error;
714	        return error.errorType;
715	    }
716	    return NO_ERROR;
717	}
