30	LinearOpsRunner::LinearOpsRunner(const infer::LinearParam &param)
31	    : OpsRunner("LinearOpsRunner"), param_(param)
32	{
33	    ATB_LOG(INFO) << GetLogPrefix() << "LinearOpsRunner::LinearOpsRunner";
34	
35	    elewiseAddParam_.elewiseType = AsdOps::OpParam::Elewise::ELEWISE_ADD;
36	    transdataNdToNzParam_.transdataType = AsdOps::OpParam::Transdata::ND_TO_FRACTAL_NZ;
37	    transdataNzToNdParam_.transdataType = AsdOps::OpParam::Transdata::FRACTAL_NZ_TO_ND;
38	
39	    matmulMergeAxis_ = [&](const Mki::SVector<int64_t> &oldDims, Mki::SVector<int64_t> &newDims) {
40	        if (oldDims.size() == SIZE_3) {
41	            newDims = {oldDims.at(0) * oldDims.at(1), oldDims.at(DIM_2)};
42	            ATB_LOG(INFO) << " merge axis - before: " << oldDims << "; after: " << newDims;
43	        } else {
44	            newDims = oldDims;
45	        }
46	    };
47	    matmulNzReshape_ = [&](const Mki::SVector<int64_t> &oldDims, Mki::SVector<int64_t> &newDims) {
48	        int64_t align = matmulParam_.enDequant ? INT8_ALIGN : DEFAULT_ALIGN;
49	        if (oldDims.size() == SIZE_2) {
50	            newDims = {1, UtilsInternal::AlignUp(oldDims.at(1), align) / align,
51	                       UtilsInternal::AlignUp(oldDims.at(0), DEFAULT_ALIGN), align};
52	            ATB_LOG(INFO) << " nz reshape - before: " << oldDims << "; after: " << newDims;
53	        } else if (oldDims.size() == SIZE_3) {
54	            newDims = {oldDims.at(0), UtilsInternal::AlignUp(oldDims.at(DIM_2), align) / align,
55	                       UtilsInternal::AlignUp(oldDims.at(1), DEFAULT_ALIGN), align};
56	            ATB_LOG(INFO) << " nz reshape - before: " << oldDims << "; after: " << newDims;
57	        } else {
58	            newDims = oldDims;
59	        }
60	    };
61	    transdataUnsqueeze_ = [&](const Mki::SVector<int64_t> &oldDims, Mki::SVector<int64_t> &newDims) {
62	        if (oldDims.size() == SIZE_2) {
63	            newDims = {1, oldDims.at(0), oldDims.at(1)};
64	            ATB_LOG(INFO) << GetLogPrefix() << "transdata unsqueeze - before: " << oldDims << "; after: " << newDims;
65	        } else if (oldDims.size() == SIZE_3) {
66	            newDims = {1, oldDims.at(0) * oldDims.at(1), oldDims.at(DIM_2)};
67	            ATB_LOG(INFO) << GetLogPrefix() << "transdata unsqueeze - before: " << oldDims << "; after: " << newDims;
68	        } else {
69	            newDims = oldDims;
70	        }
71	    };
72	    elewiseAddUnsqueeze_ = [&](const Mki::SVector<int64_t> &oldDims, Mki::SVector<int64_t> &newDims) {
73	        if (oldDims.size() == SIZE_2 && oldDims.at(0) != 1) {
74	            newDims = {oldDims.at(0), 1, oldDims.at(1)};
75	            ATB_LOG(INFO) << GetLogPrefix() << "elewiseAdd unsqueeze - before: " << oldDims << "; after: " << newDims;
76	        } else {
77	            newDims = oldDims;
78	        }
79	    };
80	}
