84	Status LinearOpsRunner::SetupKernelGraph(const OpsTensorPack &opsTensorPack)
85	{
86	    (void)opsTensorPack;
87	
88	    matmulParam_.transposeA = param_.transposeA;
89	    matmulParam_.transposeB = param_.transposeB;
90	    matmulParam_.enShuffleK = GetSingleton<Config>().IsMatmulShuffleKEnable();
91	    matmulParam_.enDequant = param_.outDataType != ACL_DT_UNDEFINED;
92	    matmulParam_.outDtype = static_cast<Mki::TensorDType>(param_.outDataType);
93	
94	    size_t inTensorId = 0;
95	    Mki::Tensor &xTensor = kernelGraph_.inTensors.at(inTensorId++);
96	    Mki::Tensor &weightTensor = kernelGraph_.inTensors.at(inTensorId++);
97	    isWeightNz_ = weightTensor.desc.format == Mki::TENSOR_FORMAT_FRACTAL_NZ;
98	    SetupNeedMergeAxis(xTensor, weightTensor);
99	    SetupMatmulOriShape(xTensor, weightTensor);
100	    transdataNzToNdParam_.outCrops = {matmulParam_.oriShape.at(0), matmulParam_.oriShape.at(2)};
101	    if (matmulParam_.enDequant) {
102	        if (GetSingleton<Config>().Is910B() && param_.quantMode == infer::LinearParam::PER_TOKEN) {
103	                return SetupKernelGraphMatmulDequantPerToken910B();
104	        } else if (GetSingleton<Config>().Is910B() || GetSingleton<Config>().Is310B()) {
105	            return SetupKernelGraphMatmulDequant910B();
106	        }
107	        return isWeightNz_ ? SetupKernelGraphMatmulDequantWeightNzNot910B() :
108	                             SetupKernelGraphMatmulDequantWeightNdNot910B();
109	    }
110	    if (param_.enAccum) {
111	        return SetupKernelGraphMatmulAccum();
112	    }
113	    if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
114	        return param_.hasBias ? SetupKernelGraphMatmulEinElewiseAdd() : SetupKernelGraphMatmulEin();
115	    }
116	    if (param_.hasBias) {
117	        Mki::Tensor &biasTensor = kernelGraph_.inTensors.at(inTensorId++);
118	        if (biasTensor.desc.dtype == Mki::TENSOR_DTYPE_FLOAT) {
119	            return SetupKernelGraphMatmulWithBias();
120	        }
121	        if (GetSingleton<Config>().Is910B() || GetSingleton<Config>().Is310B()) {
122	            return SetupKernelGraphMatmulElewiseAdd910B();
123	        }
124	        return isWeightNz_ ? SetupKernelGraphMatmulElewiseAddWeightNzNot910B() :
125	                             SetupKernelGraphMatmulElewiseAddWeightNdNot910B();
126	    } else {
127	        if (xTensor.desc.dtype == Mki::TENSOR_DTYPE_FLOAT && weightTensor.desc.dtype == Mki::TENSOR_DTYPE_FLOAT) {
128	            moeGateCorrParam_.transposeA = param_.transposeA;
129	            moeGateCorrParam_.transposeB = param_.transposeB;
130	            return SetupKernelGraphMoeGateCorr();
131	        }
132	        if (GetSingleton<Config>().Is910B() || GetSingleton<Config>().Is310B()) {
133	            return SetupKernelGraphMatmul910B();
134	        }
135	        return isWeightNz_ ? SetupKernelGraphMatmulWeightNzNot910B() : SetupKernelGraphMatmulWeightNdNot910B();
136	    }
137	}
