139	Status LinearOpsRunner::SetupKernelGraphMatmul910B()
140	{
141	    ATB_LOG(INFO) << GetLogPrefix() << "LinearOpsRunner::SetupKernelGraphMatmulA2";
142	
143	    InitKernelGraph(SIZE_2, 1, 0, 1);
144	
145	    Mki::Tensor &xTensor = kernelGraph_.inTensors.at(0);
146	    Mki::Tensor &weightTensor = kernelGraph_.inTensors.at(1);
147	
148	    Mki::Tensor &outTensor = kernelGraph_.outTensors.at(0);
149	
150	    KernelGraphNode &matmulNode = kernelGraph_.nodes.at(0);
151	
152	    matmulNode.opDesc = {0, "MatMulOperation", matmulParam_};
153	    matmulNode.inTensors = {&xTensor, &weightTensor};
154	    matmulNode.outTensors = {&outTensor};
155	    matmulNode.inTensorViewFuncs.resize(matmulNode.inTensors.size());
156	    if (xNeedMergeAxis_) {
157	        matmulNode.inTensorViewFuncs.at(0) = matmulMergeAxis_;
158	    }
159	    if (isWeightNz_) {
160	        matmulNode.inTensorViewFuncs.at(1) = matmulNzReshape_;
161	    } else if (weightNeedMergeAxis_) {
162	        matmulNode.inTensorViewFuncs.at(1) = matmulMergeAxis_;
163	    }
164	
165	    return NO_ERROR;
