168	Status LinearOpsRunner::SetupKernelGraphMatmulWeightNdNot910B()
169	{
170	    ATB_LOG(INFO) << GetLogPrefix() << "LinearOpsRunner::SetupKernelGraphMatmulWeightNdNotA2";
171	
172	    InitKernelGraph(SIZE_2, 1, SIZE_3, SIZE_4);
173	
174	    Mki::Tensor &xTensor = kernelGraph_.inTensors.at(0);
175	    Mki::Tensor &weightTensor = kernelGraph_.inTensors.at(1);
176	
177	    Mki::Tensor &outTensor = kernelGraph_.outTensors.at(0);
178	
179	    size_t internalTensorId = 0;
180	    Mki::Tensor &transdataAOutTensor = kernelGraph_.internalTensors.at(internalTensorId++);
181	    Mki::Tensor &transdataBOutTensor = kernelGraph_.internalTensors.at(internalTensorId++);
182	    Mki::Tensor &matmulOutTensor = kernelGraph_.internalTensors.at(internalTensorId++);
183	
184	    size_t nodeId = 0;
185	    KernelGraphNode &transdataANode = kernelGraph_.nodes.at(nodeId++);
186	    KernelGraphNode &transdataBNode = kernelGraph_.nodes.at(nodeId++);
187	    KernelGraphNode &matmulNode = kernelGraph_.nodes.at(nodeId++);
188	    KernelGraphNode &transdataOutNode = kernelGraph_.nodes.at(nodeId++);
189	
190	    transdataANode.opDesc = {0, "TransdataOperation", transdataNdToNzParam_};
191	    transdataANode.inTensors = {&xTensor};
192	    transdataANode.outTensors = {&transdataAOutTensor};
193	    transdataANode.inTensorViewFuncs.resize(transdataANode.inTensors.size());
194	    if (xTensor.desc.dims.size() == SIZE_2 || xNeedMergeAxis_) {
195	        transdataANode.inTensorViewFuncs.at(0) = transdataUnsqueeze_;
196	    }
197	
198	    transdataBNode.opDesc = {0, "TransdataOperation", transdataNdToNzParam_};
199	    transdataBNode.inTensors = {&weightTensor};
200	    transdataBNode.outTensors = {&transdataBOutTensor};
201	    transdataBNode.inTensorViewFuncs.resize(transdataBNode.inTensors.size());
202	    if (weightTensor.desc.dims.size() == SIZE_2) {
203	        transdataBNode.inTensorViewFuncs.at(0) = transdataUnsqueeze_;
204	    }
205	
206	    matmulNode.opDesc = {0, "MatMulOperation", matmulParam_};
207	    matmulNode.inTensors = {&transdataAOutTensor, &transdataBOutTensor};
208	    matmulNode.outTensors = {&matmulOutTensor};
209	
210	    transdataOutNode.opDesc = {0, "TransdataOperation", transdataNzToNdParam_};
211	    transdataOutNode.inTensors = {&matmulOutTensor};
212	    transdataOutNode.outTensors = {&outTensor};
213	
214	    return NO_ERROR;
215	}
