683	    transdataBNode.opDesc = {0, "TransdataOperation", transdataNdToNzParam_};
684	    transdataBNode.inTensors = {&weightTensor};
685	    transdataBNode.outTensors = {&transdataBOutTensor};
686	    transdataBNode.inTensorViewFuncs.resize(transdataBNode.inTensors.size());
687	    if (weightTensor.desc.dims.size() == SIZE_2) {
688	        transdataBNode.inTensorViewFuncs.at(0) = transdataUnsqueeze_;
689	    }
690	
691	    matmulParam_.withBias = param_.hasBias;
692	    matmulNode.opDesc = {0, "MatMulOperation", matmulParam_};
693	    matmulNode.inTensors = {&transdataAOutTensor, &transdataBOutTensor, &biasTensor, &deqScaleTensor, &perTokenScaleTensor};
694	    matmulNode.outTensors = {&matmulOutTensor};
695	
696	    transdataOutNode.opDesc = {0, "TransdataOperation", transdataNzToNdParam_};
697	    transdataOutNode.inTensors = {&matmulOutTensor};
698	    transdataOutNode.outTensors = {&outTensor};
699	
700	    return NO_ERROR;
701	}
702	
703	Status LinearOpsRunner::SetupKernelGraphMatmulDequantWeightNzNot910B()
704	{
705	    ATB_LOG(INFO) << GetLogPrefix() << "SetupKernelGraphMatmulDequantWeightNzNotA2";
706	
707	    size_t inTensorNum = param_.hasBias ? SIZE_4 : SIZE_3;
708	    if (param_.hasBias) {
709	        matmulParam_.quantMode = AsdOps::OpParam::MatMul::QuantMode::PER_CHANNEL_ASYMM;
710	    } else {
711	        matmulParam_.quantMode = AsdOps::OpParam::MatMul::QuantMode::PER_CHANNEL_SYMM;
712	    }
713	    InitKernelGraph(inTensorNum, 1, SIZE_2, SIZE_3);
714	
715	    size_t inTensorId = 0;
716	    Mki::Tensor &xTensor = kernelGraph_.inTensors.at(inTensorId++);
717	    Mki::Tensor &weightTensor = kernelGraph_.inTensors.at(inTensorId++);
718	    Mki::Tensor &biasTensor = param_.hasBias ? kernelGraph_.inTensors.at(inTensorId++) : nullTensor_;
719	    Mki::Tensor &deqScaleTensor = kernelGraph_.inTensors.at(inTensorId++);
720	    Mki::Tensor &perTokenScaleTensor = nullTensor_;
721	
722	    Mki::Tensor &outTensor = kernelGraph_.outTensors.at(0);
723	
724	    Mki::Tensor &transdataAOutTensor = kernelGraph_.internalTensors.at(0);
725	    Mki::Tensor &matmulOutTensor = kernelGraph_.internalTensors.at(1);
726	
727	    size_t nodeId = 0;
728	    KernelGraphNode &transdataANode = kernelGraph_.nodes.at(nodeId++);
729	    KernelGraphNode &matmulNode = kernelGraph_.nodes.at(nodeId++);
730	    KernelGraphNode &transdataOutNode = kernelGraph_.nodes.at(nodeId++);
731	
732	    transdataANode.opDesc = {0, "TransdataOperation", transdataNdToNzParam_};
733	    transdataANode.inTensors = {&xTensor};
734	    transdataANode.outTensors = {&transdataAOutTensor};
735	    transdataANode.inTensorViewFuncs.resize(transdataANode.inTensors.size());
736	    if (xTensor.desc.dims.size() == SIZE_2 || xNeedMergeAxis_) {
737	        transdataANode.inTensorViewFuncs.at(0) = transdataUnsqueeze_;
738	    }
739	
740	    matmulParam_.withBias = param_.hasBias;
741	    matmulNode.opDesc = {0, "MatMulOperation", matmulParam_};
742	    matmulNode.inTensors = {&transdataAOutTensor, &weightTensor, &biasTensor, &deqScaleTensor, &perTokenScaleTensor};
743	    matmulNode.outTensors = {&matmulOutTensor};
744	    matmulNode.inTensorViewFuncs.resize(matmulNode.inTensors.size());
745	    if (isWeightNz_) {
746	        matmulNode.inTensorViewFuncs.at(1) = matmulNzReshape_;
747	    }
748	
749	    transdataOutNode.opDesc = {0, "TransdataOperation", transdataNzToNdParam_};
750	    transdataOutNode.inTensors = {&matmulOutTensor};
751	    transdataOutNode.outTensors = {&outTensor};
752	
753	    return NO_ERROR;
754	}
755	
756	Status LinearOpsRunner::SetupKernelGraphMoeGateCorr()
757	{
758	    ATB_LOG(INFO) << GetLogPrefix() << "LinearOpsRunner::SetupKernelGraphMoeGateCorr";
759	
760	    InitKernelGraph(SIZE_2, 1, 0, 1);
761	
762	    Mki::Tensor &xTensor = kernelGraph_.inTensors.at(0);
763	    Mki::Tensor &weightTensor = kernelGraph_.inTensors.at(1);
764	    Mki::Tensor &outTensor = kernelGraph_.outTensors.at(0);
765	
766	    KernelGraphNode &matmulNode = kernelGraph_.nodes.at(0);
767	
768	    matmulNode.opDesc = {0, "MoeGateCorrOperation", moeGateCorrParam_};
769	    matmulNode.inTensors = {&xTensor, &weightTensor};
770	    matmulNode.outTensors = {&outTensor};
771	
772	    return NO_ERROR;
773	}
774	
775	void LinearOpsRunner::SetupMatmulOriShape(const Mki::Tensor &xTensor, const Mki::Tensor &weightTensor)
776	{
777	    if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
778	        SetupMatmulOriShapeEin(xTensor, weightTensor);
779	    } else {
780	        int64_t &m = matmulParam_.oriShape.at(0);
781	        int64_t &k = matmulParam_.oriShape.at(1);
782	        int64_t &n = matmulParam_.oriShape.at(DIM_2);
783	        if (xTensor.desc.dims.size() == SIZE_2) {
784	            m = param_.transposeA ? xTensor.desc.dims.at(1) : xTensor.desc.dims.at(0);
785	            k = param_.transposeA ? xTensor.desc.dims.at(0) : xTensor.desc.dims.at(1);
786	        } else if (xTensor.desc.dims.size() == SIZE_3) {
787	            m = param_.transposeA ? xTensor.desc.dims.at(DIM_2) : xTensor.desc.dims.at(1);
788	            if (xNeedMergeAxis_) {
789	                m *= xTensor.desc.dims.at(0);
790	            }
791	            k = param_.transposeA ? xTensor.desc.dims.at(1) : xTensor.desc.dims.at(DIM_2);
792	        }
793	        if (weightTensor.desc.dims.size() == SIZE_2) {
794	            n = param_.transposeB ? weightTensor.desc.dims.at(0) : weightTensor.desc.dims.at(1);
795	        } else if (weightTensor.desc.dims.size() == SIZE_3) {
796	            n = param_.transposeB ? weightTensor.desc.dims.at(1) : weightTensor.desc.dims.at(DIM_2);
797	        } else if (weightTensor.desc.dims.size() == SIZE_4) {
798	            n = param_.transposeB ? weightTensor.desc.dims.at(DIM_2) :
799	                                    weightTensor.desc.dims.at(1) * weightTensor.desc.dims.at(DIM_3);
800	        }
801	    }
802	}
803	
804	void LinearOpsRunner::SetupMatmulOriShapeEin(const Mki::Tensor &xTensor, const Mki::Tensor &weightTensor)
805	{
806	    int64_t &m = matmulParam_.oriShape.at(0);
807	    int64_t &k = matmulParam_.oriShape.at(1);
808	    int64_t &n = matmulParam_.oriShape.at(DIM_2);
809	    m = param_.transposeA ? xTensor.desc.dims.at(DIM_2) : xTensor.desc.dims.at(0);
810	    k = param_.transposeA ? xTensor.desc.dims.at(0) : xTensor.desc.dims.at(DIM_2);
811	    if (weightTensor.desc.format == Mki::TensorFormat::TENSOR_FORMAT_ND) {
812	        n = param_.transposeB ? weightTensor.desc.dims.at(1) : weightTensor.desc.dims.at(DIM_2);
813	    } else if (weightTensor.desc.format == Mki::TensorFormat::TENSOR_FORMAT_FRACTAL_NZ) {
814	        n = param_.transposeB ? weightTensor.desc.dims.at(DIM_2) :
815	                                weightTensor.desc.dims.at(1) * weightTensor.desc.dims.at(DIM_3);
816	    }
817	}
818	
819	void LinearOpsRunner::InitKernelGraph(size_t inTensorNum, size_t outTensorNum, size_t internalTensorNum, size_t nodeNum)
820	{
821	    kernelGraph_.inTensors.resize(inTensorNum);
822	    kernelGraph_.outTensors.resize(outTensorNum);
823	    kernelGraph_.internalTensors.resize(internalTensorNum);
824	    kernelGraph_.nodes.resize(nodeNum);
825	}
826	
827	void LinearOpsRunner::SetupNeedMergeAxis(const Mki::Tensor &xTensor, const Mki::Tensor &weightTensor)
828	{
829	    xNeedMergeAxis_ = false;
830	    weightNeedMergeAxis_ = false;
831	    if (xTensor.desc.dims.size() == SIZE_2) {
832	        weightNeedMergeAxis_ = weightTensor.desc.dims.size() == SIZE_3;
833	    } else if (xTensor.desc.dims.size() == SIZE_3) {
834	        if (weightTensor.desc.dims.size() == SIZE_2) {
835	            xNeedMergeAxis_ = true;
836	        } else {
837	            if (xTensor.desc.dims.at(0) != 1 && weightTensor.desc.dims.at(0) == 1) {
838	                xNeedMergeAxis_ = true;
839	                weightNeedMergeAxis_ = weightTensor.desc.dims.size() == SIZE_3;
840	            }
841	        }
842	    }
843	}
844	
845	REG_RUNNER_TYPE(LinearOpsRunner);
846	REG_OP_PARAM(AsdOps::OpParam::Transdata);
847	REG_OP_PARAM(AsdOps::OpParam::MatMul);
848	REG_OP_PARAM(AsdOps::OpParam::MoeGateCorr);
849	} // namespace atb

