57	bool CheckType(const infer::LinearParallelParam &opParam, Status &isOK)
58	{
59	    if (opParam.type <= atb::infer::LinearParallelParam::ParallelType::UNDEFINED ||
60	        opParam.type >= atb::infer::LinearParallelParam::ParallelType::MAX) {
61	        ATB_LOG(ERROR) << "LinearParallel type:" << opParam.type << " is invalid ParallelType";
62	        isOK = ERROR_INVALID_PARAM;
63	        return true;
64	    }
65	    if (opParam.type != atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR && opParam.keepIntermediate) {
66	        ATB_LOG(ERROR) << "LinearParallel backend lcoc only ALL_GATHER_LINEAR support keepIntermediate is true";
67	        isOK = ERROR_INVALID_PARAM;
68	        return true;
69	    }
70	    if (opParam.quantType == atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_PER_TOKEN &&
71	        opParam.type != atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM &&
72	        opParam.type != atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC &&
73	        opParam.type != atb::infer::LinearParallelParam::ParallelType::LINEAR_ALL_REDUCE) {
74	        ATB_LOG(ERROR) << "When LinearParallel backend is lcoc, "
75	                       << "only ALLTOALLVC_ALL_GATHER_GMM, GMM_REDUCE_SCATTER_ALLTOALLVC and LINEAR_ALL_REDUCE"
76	                       << " support quantType[QUANT_TYPE_PER_TOKEN]";
77	        isOK = ERROR_INVALID_PARAM;
78	        return true;
79	    }
80	    if (opParam.type == atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM ||
81	        opParam.type == atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC) {
82	        if (opParam.moeInfo.epSize * opParam.moeInfo.tpSize != opParam.rankSize) {
83	            ATB_LOG(ERROR) << "ep * tp should equal to rankSize";
84	            isOK = ERROR_INVALID_PARAM;
85	            return true;
86	        }
87	        if (opParam.moeInfo.localExpertNums < static_cast<int16_t>(LOCAL_EXPERT_NUMS_MIN) ||
88	            opParam.moeInfo.localExpertNums > static_cast<int16_t>(LOCAL_EXPERT_NUMS_MAX)) {
89	            ATB_LOG(ERROR) << "localExpertNums should between 1 and 16";
90	            isOK = ERROR_INVALID_PARAM;
91	            return true;
92	        }
93	        if (opParam.quantType != atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_UNDEFINED &&
94	            opParam.quantType != atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_PER_CHANNEL &&
95	            opParam.quantType != atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_PER_TOKEN) {
96	            ATB_LOG(ERROR) << "LinearParallel type:" << opParam.type
97	                           << " support QuantType is QUANT_TYPE_UNDEFINED/QUANT_TYPE_PER_CHANNEL/QUANT_TYPE_PER_TOKEN";
98	            isOK = ERROR_INVALID_PARAM;
99	            return true;
100	        }
101	    }
102	    return false;
103	}
