105	bool CheckTypeMc2(const infer::LinearParallelParam &opParam, Status &isOK)
106	{
107	    if (opParam.hasResidual) {
108	        ATB_LOG(ERROR) << "When LinearParallel backend is mc2, not support residual";
109	        isOK = ERROR_INVALID_PARAM;
110	        return true;
111	    }
112	    if (opParam.commMode != atb::infer::CommMode::COMM_MULTI_THREAD) {
113	        ATB_LOG(ERROR) << "When LinearParallel backend is mc2, only support commMode[COMM_MULTI_THREAD]";
114	        isOK = ERROR_INVALID_PARAM;
115	        return true;
116	    }
117	    if (opParam.quantType != atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_UNDEFINED ||
118	        opParam.quantType != atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_UNQUANT) {
119	        ATB_LOG(ERROR)
120	            << "When LinearParallel backend is mc2, only support quantType[QUANT_TYPE_UNDEFINED][QUANT_TYPE_UNQUANT]";
121	        isOK = ERROR_INVALID_PARAM;
122	        return true;
123	    }
124	    if (opParam.type != infer::LinearParallelParam::ParallelType::LINEAR_REDUCE_SCATTER) {
125	        ATB_LOG(ERROR)
126	            << "When LinearParallel backend is mc2, only support type[LINEAR_REDUCE_SCATTER], LinearParallel type:"
127	            << opParam.type << " is invalid ParallelType";
128	        isOK = ERROR_INVALID_PARAM;
129	        return true;
130	    }
131	    return false;
132	}
