134	template <> Status CreateOperation(const infer::LinearParallelParam &opParam, Operation **operation)
135	{
136	    if (operation == nullptr) {
137	        return ERROR_INVALID_PARAM;
138	    }
139	    OP_PARAM_RSV_CHECK(opParam);
140	    if (OperationUtil::DistributedInitCheck<infer::LinearParallelParam>(opParam) != NO_ERROR) {
141	        ATB_LOG(ERROR) << "LinearParallelOperation DistributedInitCheck failed.";
142	        return ERROR_INVALID_PARAM;
143	    }
144	    int rankSize = opParam.rankSize;
145	    if ((opParam.rankSize <= 0 || (static_cast<uint32_t>(rankSize) & static_cast<uint32_t>(rankSize - 1)) != 0) &&
146	        opParam.backend == "lcoc") {
147	        ATB_LOG(ERROR) << "LinearParallel rankSize support power of 2 but got [" << opParam.rankSize << "]";
148	        return ERROR_INVALID_PARAM;
149	    }
150	    if (opParam.backend != "hccl" && opParam.backend != "lccl" && opParam.backend != "lcoc" &&
151	        opParam.backend != "mc2") {
152	        ATB_LOG(ERROR) << "LinearParallel backend support hccl/lccl/lcoc/mc2 but get [" << opParam.backend << "]";
153	        return ERROR_INVALID_PARAM;
154	    }
155	    if (opParam.backend == "lcoc") {
156	        Status isOk;
157	        if (CheckType(opParam, isOk))
158	            return isOk;
159	    }
160	    if (opParam.backend == "mc2") {
161	        Status isOk;
162	        if (CheckTypeMc2(opParam, isOk)) {
163	            return isOk;
164	        }
165	        isOk = LinearParallelAclnnRunner::LoadMethodMatmulReduceScatter();
166	        if (isOk != NO_ERROR) {
167	            return isOk;
168	        }
169	    }
170	    Status status = LinearParallelAclnnRunner::LoadMethodMatmulReduceScatter();
171	    if (status != NO_ERROR) {
172	        ATB_LOG(ERROR) << "Load Aclnn functions failed!";
173	        return ERROR_INVALID_PARAM;
174	    }
175	    *operation = new (std::nothrow) LinearParallelOperation(opParam);
176	    if (*operation == nullptr) {
177	        ATB_LOG(ERROR) << "failed to new operation";
178	        return ERROR_OUT_OF_HOST_MEMORY;
179	    }
180	    return NO_ERROR;
181	}
