190	    if (param_.backend == "lcoc" || param_.backend == "mc2") {
191	        opIrKeySs << (param_.backend == "lcoc" ? "Lcoc" : "Mc2");
192	        if (param_.keepIntermediate) {
193	            opIrKeySs << "KeepIntermediate";
194	        }
195	        if (param_.type == atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM ||
196	            param_.type == atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC) {
197	            opIrKeySs << "Moe";
198	        }
199	        if (commonCheckParam_.isQuant) {
200	            opIrKeySs << "Quant";
201	            if (param_.quantType == atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_PER_TOKEN) {
202	                opIrKeySs << "PerToken";
203	            }
204	        }
205	    }
206	    std::string opIrKey = opIrKeySs.str();
207	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(opIrKey);
