212	uint32_t LinearParallelOperation::GetInputNum() const
213	{
214	    bool isMoe = false;
215	    if (param_.type == atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM ||
216	        param_.type == atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC) {
217	        isMoe = true;
218	    }
219	    uint32_t inTensorNum = param_.hasResidual ? IN_TENSOR_NUM_WITH_RESIDUAL : IN_TENSOR_NUM_WITHOUT_RESIDUAL;
220	    if (isMoe) {
221	        inTensorNum += IN_TENSOR_NUM_WITH_MOE;
222	    }
223	    if (commonCheckParam_.isQuant) {
224	        if (isMoe) {
225	            inTensorNum -= MOE_IN_TENSOR_NUM_REMOVE_OFFSET;
226	        }
227	        inTensorNum += EXTRA_IN_TENSOR_NUM_WITH_QUANT;
228	        if (param_.quantType == atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_PER_TOKEN) {
229	            inTensorNum += EXTRA_IN_TENSOR_NUM_WITH_PER_TOKEN_QUANT;
230	        }
231	    }
232	    return inTensorNum;
