240	Status LinearParallelOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
241	                                               SVector<TensorDesc> &outTensorDescs) const
242	{
243	    if (param_.backend != "lcoc" && param_.backend != "mc2") {
244	        return OperationUtil::MatmulInferShape(inTensorDescs, outTensorDescs, commonCheckParam_);
245	    }
246	    switch (param_.type) {
247	        case atb::infer::LinearParallelParam::ParallelType::LINEAR_ALL_REDUCE:
248	        case atb::infer::LinearParallelParam::ParallelType::PURE_LINEAR:
249	            return OperationUtil::MatmulInferShape(inTensorDescs, outTensorDescs, commonCheckParam_);
250	        case atb::infer::LinearParallelParam::ParallelType::LINEAR_REDUCE_SCATTER:
251	            return InferShapeLinearReduceScatter(inTensorDescs, outTensorDescs);
252	        case atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR:
253	            return InferShapeAllGatherLinear(inTensorDescs, outTensorDescs);
254	        case atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR_REDUCE_SCATTER:
255	            return InferShapeAllGatherLinearReduceScatter(inTensorDescs, outTensorDescs);
256	        case atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM:
257	        case atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC:
258	            return InferShapeAllToAllvcAllGatherGmm(inTensorDescs, outTensorDescs);
259	        default:
260	            ATB_LOG(ERROR) << "not support type:" << param_.type;
261	            return ERROR_INVALID_PARAM;
262	    }
263	}
