266	Status LinearParallelOperation::InferShapeLinearReduceScatter(const SVector<TensorDesc> &inTensorDescs,
267	                                                              SVector<TensorDesc> &outTensorDescs) const
268	{
269	    Status st = OperationUtil::MatmulInferShape(inTensorDescs, outTensorDescs, commonCheckParam_);
270	    if (st != NO_ERROR) {
271	        return st;
272	    }
273	    if (outTensorDescs.at(0).shape.dims[0] == 1) {
274	        if (outTensorDescs.at(0).shape.dims[1] % param_.rankSize != 0) {
275	            return ERROR_INVALID_TENSOR_DIM;
276	        }
277	        outTensorDescs.at(0).shape.dims[1] /= param_.rankSize;
278	    } else {
279	        if (outTensorDescs.at(0).shape.dims[0] % param_.rankSize != 0) {
280	            return ERROR_INVALID_TENSOR_DIM;
281	        }
282	        outTensorDescs.at(0).shape.dims[0] /= param_.rankSize;
283	    }
284	    return NO_ERROR;
285	}
