287	Status LinearParallelOperation::InferShapeAllGatherLinear(const SVector<TensorDesc> &inTensorDescs,
288	                                                          SVector<TensorDesc> &outTensorDescs) const
289	{
290	    SVector<TensorDesc> newInTensorDescs;
291	    newInTensorDescs = inTensorDescs;
292	    newInTensorDescs.at(0).shape.dims[0] *= param_.rankSize;
293	    Status st = OperationUtil::MatmulInferShape(newInTensorDescs, outTensorDescs, commonCheckParam_);
294	    if (st != NO_ERROR) {
295	        return st;
296	    }
297	    if (outTensorDescs.size() == OUT_TENSOR_NUM_WITH_MID) {
298	        outTensorDescs.at(1) = inTensorDescs.at(0);
299	        outTensorDescs.at(1).shape.dims[0] *= param_.rankSize;
300	    }
301	    return NO_ERROR;
302	}
