305	                                                                       SVector<TensorDesc> &outTensorDescs) const
306	{
307	    SVector<TensorDesc> newInTensorDescs;
308	    newInTensorDescs = inTensorDescs;
309	    newInTensorDescs.at(0).shape.dims[0] *= param_.twoDimTPInfo.agDim;
310	    Status st = OperationUtil::MatmulInferShape(newInTensorDescs, outTensorDescs, commonCheckParam_);
311	    if (st != NO_ERROR) {
