318	Status LinearParallelOperation::InferShapeAllToAllvcAllGatherGmm(const SVector<TensorDesc> &inTensorDescs,
319	                                                                 SVector<TensorDesc> &outTensorDescs) const
320	{
321	    Status st = OperationUtil::MatmulInferShape(inTensorDescs, outTensorDescs, commonCheckParam_);
322	    if (st != NO_ERROR) {
323	        return st;
324	    }
325	    uint32_t maxOutputSize = inTensorDescs.at(inTensorDescs.size() - 1).shape.dims[0];
326	    if (maxOutputSize > MAX_OUTPUT_SIZE) {
327	        ATB_LOG(ERROR) << GetLogPrefix() << "maxOutputSize is too large." << maxOutputSize;
328	        return ERROR_INVALID_TENSOR_SIZE;
329	    }
330	    uint32_t k = inTensorDescs.at(0).shape.dims[1];
331	    if (k > MAX_K) {
332	        ATB_LOG(ERROR) << GetLogPrefix() << "K is too large. should be 1 to 24000, now is " << k;
333	        return ERROR_INVALID_TENSOR_SIZE;
334	    }
335	    outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(inTensorDescs.size() - 1).shape.dims[0];
336	    return NO_ERROR;
337	}
