339	Status LinearParallelOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
340	{
341	    if (param_.backend != "lcoc" && param_.backend != "mc2") {
342	        return InferShapeCheckLinearAllReduce(inTensorDescs);
343	    }
344	    switch (param_.type) {
345	        case atb::infer::LinearParallelParam::ParallelType::LINEAR_ALL_REDUCE:
346	        case atb::infer::LinearParallelParam::ParallelType::PURE_LINEAR:
347	            return InferShapeCheckLinearAllReduce(inTensorDescs);
348	        case atb::infer::LinearParallelParam::ParallelType::LINEAR_REDUCE_SCATTER:
349	            return InferShapeCheckLinearReduceScatter(inTensorDescs);
350	        case atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR:
351	            return InferShapeCheckAllGatherLinear(inTensorDescs);
352	        case atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR_REDUCE_SCATTER:
353	            return InferShapeCheckAllGatherLinearReduceScatter(inTensorDescs);
354	        case atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM:
355	        case atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC:
356	            return InferShapeCheckAllToAllvcAllGatherGmm(inTensorDescs);
357	        default:
358	            ATB_LOG(ERROR) << GetLogPrefix() << "not support type:" << param_.type;
359	            return ERROR_INVALID_PARAM;
360	    }
361	}
