363	Status LinearParallelOperation::CheckResidual(const SVector<TensorDesc> &inTensorDescs) const
364	{
365	    if (param_.hasResidual) {
366	        int64_t n = OperationUtil::GetYTensorN(inTensorDescs.at(1), param_.transWeight);
367	        size_t residualTensorId = inTensorDescs.size();
368	        if (param_.type == atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM ||
369	            param_.type == atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC) {
370	            residualTensorId -= commonCheckParam_.isQuant ? RESIDUAL_TENSOR_INDEX_4 : RESIDUAL_TENSOR_INDEX_3;
371	        } else {
372	            residualTensorId -= 1;
373	        }
374	        const TensorDesc &residual = inTensorDescs.at(residualTensorId);
375	        int64_t needFirstDim = 1;
376	        if (!OperationUtil::LinearBiasDeqCheck(residual, GetLogPrefix(), n, needFirstDim, residualTensorId)) {
377	            ATB_LOG(ERROR) << GetLogPrefix() << "Check residual tensor failed.";
378	            return ERROR_INVALID_TENSOR_DIM;
379	        }
380	    }
381	    return NO_ERROR;
382	}
