385	Status LinearParallelOperation::InferShapeCheckLinearAllReduce(const SVector<TensorDesc> &inTensorDescs) const
386	{
387	    if (!OperationUtil::MatmulInTensorDescsCheck(inTensorDescs, GetLogPrefix(), commonCheckParam_)) {
388	        return ERROR_INVALID_TENSOR_DIM;
389	    }
390	
391	    bool isQuant = param_.quantType > infer::LinearParallelParam::QuantType::QUANT_TYPE_UNQUANT &&
392	                   param_.quantType < infer::LinearParallelParam::QuantType::QUANT_TYPE_MAX;
393	    if (isQuant && inTensorDescs.at(3).dtype == ACL_FLOAT && param_.outDataType == ACL_FLOAT16) {
394	        ATB_LOG(ERROR) << GetLogPrefix() << "when perChannelScale's type is float, "
395	                       << "outputDataType do not support float16_t";
396	        return ERROR_INVALID_TENSOR_INI_MATCH;
397	    }
398	
399	    return CheckResidual(inTensorDescs);
400	}
