402	Status LinearParallelOperation::InferShapeCheckLinearReduceScatter(const SVector<TensorDesc> &inTensorDescs) const
403	{
404	    if (!OperationUtil::MatmulInTensorDescsCheck(inTensorDescs, GetLogPrefix(), commonCheckParam_)) {
405	        return ERROR_INVALID_TENSOR_DIM;
406	    }
407	
408	    bool isQuant = param_.quantType > infer::LinearParallelParam::QuantType::QUANT_TYPE_UNQUANT &&
409	                   param_.quantType < infer::LinearParallelParam::QuantType::QUANT_TYPE_MAX;
410	    if (isQuant && inTensorDescs.at(3).dtype == ACL_FLOAT && param_.outDataType == ACL_FLOAT16) {
411	        ATB_LOG(ERROR) << GetLogPrefix() << "when perChannelScale's type is float, "
412	                       << "outputDataType do not support float16_t";
413	        return ERROR_INVALID_TENSOR_INI_MATCH;
414	    }
415	
416	    if (param_.backend == "mc2") {
417	        if (inTensorDescs.at(0).shape.dimNum != IN_TENSOR_DIM_NUM) {
418	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dimNum should be equal to 2";
419	            return ERROR_INVALID_TENSOR_DIM_NUM;
420	        }
421	        if (inTensorDescs.at(1).shape.dimNum != IN_TENSOR_DIM_NUM) {
422	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor1 dimNum should be equal to 2";
423	            return ERROR_INVALID_TENSOR_DIM_NUM;
424	        }
425	        int64_t xTensorK = OperationUtil::GetXTensorK(inTensorDescs.at(0));
426	        if (xTensorK < 256 || xTensorK >= 65535) {
427	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 k [" << xTensorK
428	                           << "] should be an integer between [256 ~ 65535)";
429	            return ERROR_INVALID_TENSOR_DIM;
430	        }
431	    }
432	    return CheckResidual(inTensorDescs);
433	}
434	
435	Status LinearParallelOperation::InferShapeCheckAllGatherLinear(const SVector<TensorDesc> &inTensorDescs) const
436	{
437	    bool isQuant = param_.quantType > infer::LinearParallelParam::QuantType::QUANT_TYPE_UNQUANT &&
438	                   param_.quantType < infer::LinearParallelParam::QuantType::QUANT_TYPE_MAX;
439	    if (isQuant && inTensorDescs.at(3).dtype == ACL_FLOAT && param_.outDataType == ACL_FLOAT16) {
440	        ATB_LOG(ERROR) << GetLogPrefix() << "when perChannelScale's type is float, "
441	                       << "outputDataType do not support float16_t";
442	        return ERROR_INVALID_TENSOR_INI_MATCH;
443	    }
444	
445	    SVector<TensorDesc> newInTensorDescs;
446	    newInTensorDescs = inTensorDescs;
447	    newInTensorDescs.at(0).shape.dims[0] *= param_.rankSize;
448	    ATB_LOG(INFO) << GetLogPrefix() << "matmul input dim0: " << newInTensorDescs.at(0).shape.dims[0];
449	    if (!OperationUtil::MatmulInTensorDescsCheck(newInTensorDescs, GetLogPrefix(), commonCheckParam_)) {
450	        return ERROR_INVALID_TENSOR_DIM;
451	    }
452	    return CheckResidual(inTensorDescs);
453	}
454	
455	Status LinearParallelOperation::InferShapeCheckAllGatherLinearReduceScatter(
456	    const SVector<TensorDesc> &inTensorDescs) const
457	{
458	    if (param_.twoDimTPInfo.rsDim * param_.twoDimTPInfo.agDim != param_.rankSize) {
459	        ATB_LOG(ERROR) << "agDim * rsDim should equal to rankSize";
460	        return ERROR_INVALID_PARAM;
461	    }
462	    if (param_.twoDimTPInfo.rsDim == 0) {
463	        ATB_LOG(ERROR) << "rsDim can't be 0";
464	        return ERROR_INVALID_PARAM;
465	    }
466	    SVector<TensorDesc> newInTensorDescs;
467	    newInTensorDescs = inTensorDescs;
468	    newInTensorDescs.at(0).shape.dims[0] *= param_.twoDimTPInfo.agDim;
469	    ATB_LOG(INFO) << GetLogPrefix() << "matmul input dim0: " << newInTensorDescs.at(0).shape.dims[0];
470	    if (!OperationUtil::MatmulInTensorDescsCheck(newInTensorDescs, GetLogPrefix(), commonCheckParam_)) {
471	        return ERROR_INVALID_TENSOR_DIM;
472	    }
473	    int64_t xTensorM = OperationUtil::GetXTensorM(inTensorDescs.at(0));
474	    if (xTensorM * param_.twoDimTPInfo.agDim % param_.twoDimTPInfo.rsDim != 0) {
475	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 m [" << xTensorM << "] times agDim ["
476	                       << param_.twoDimTPInfo.agDim
477	                       << "] should be an integer multiple of rsDim :" << param_.twoDimTPInfo.rsDim;
478	        return ERROR_INVALID_TENSOR_DIM;
479	    }
480	    return CheckResidual(inTensorDescs);
481	}
482	
483	Status LinearParallelOperation::InferShapeCheckAllToAllvcAllGatherGmm(const SVector<TensorDesc> &inTensorDescs) const
484	{
485	    bool isQuant = param_.quantType > infer::LinearParallelParam::QuantType::QUANT_TYPE_UNQUANT &&
486	                   param_.quantType < infer::LinearParallelParam::QuantType::QUANT_TYPE_MAX;
487	    if (isQuant && inTensorDescs.at(2).dtype == ACL_FLOAT && param_.outDataType == ACL_FLOAT16) {
488	        ATB_LOG(ERROR) << GetLogPrefix() << "when perChannelScale's type is float, "
489	                       << "outputDataType do not support float16_t";
490	        return ERROR_INVALID_TENSOR_INI_MATCH;
491	    }
492	
493	    int64_t globalTokensPerExpertMatrixM = OperationUtil::GetXTensorM(inTensorDescs.at(inTensorDescs.size() - 2));
494	    int64_t globalTokensPerExpertMatrixK = OperationUtil::GetXTensorK(inTensorDescs.at(inTensorDescs.size() - 2));
495	    int64_t expertNums = param_.moeInfo.epSize * param_.moeInfo.localExpertNums;
496	    if (globalTokensPerExpertMatrixM != param_.moeInfo.epSize || globalTokensPerExpertMatrixK != expertNums) {
497	        ATB_LOG(ERROR) << GetLogPrefix() << "globalTokensPerExpertMatrix m [" << globalTokensPerExpertMatrixM
498	                       << "] should equal to ep [" << param_.moeInfo.epSize << "] and globalTokensPerExpertMatrix k ["
499	                       << globalTokensPerExpertMatrixK << "] should equal to ep*localExpertNums [" << expertNums << "]";
500	        return ERROR_INVALID_TENSOR_DIM;
501	    }
502	    return CheckResidual(inTensorDescs);
503	}
504	
505	Status LinearParallelOperation::SetupCheckImpl(const SVector<Tensor> &inTensors,
506	                                               const SVector<Tensor> &outTensors) const
507	{
508	    SVector<TensorDesc> inTensorDescs = {};
509	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
510	    SVector<TensorDesc> outTensorDescs = {};
511	    OperationUtil::InTensorsToInTensorDescs(outTensors, outTensorDescs);
512	
513	    switch (param_.type) {
514	        case atb::infer::LinearParallelParam::ParallelType::LINEAR_ALL_REDUCE:
515	        case atb::infer::LinearParallelParam::ParallelType::PURE_LINEAR:
516	            return SetupCheckLinearAllReduce(inTensorDescs, outTensorDescs.at(0));
517	        case atb::infer::LinearParallelParam::ParallelType::LINEAR_REDUCE_SCATTER:
518	            return SetupCheckLinearReduceScatter(inTensorDescs, outTensorDescs.at(0));
519	        case atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR:
520	            return SetupCheckAllGatherLinear(inTensorDescs, outTensorDescs);
521	        case atb::infer::LinearParallelParam::ParallelType::ALL_GATHER_LINEAR_REDUCE_SCATTER:
522	            return SetupCheckAllGatherLinearReduceScatter(inTensorDescs, outTensorDescs.at(0));
523	        case atb::infer::LinearParallelParam::ParallelType::ALLTOALLVC_ALL_GATHER_GMM:
524	        case atb::infer::LinearParallelParam::ParallelType::GMM_REDUCE_SCATTER_ALLTOALLVC:
525	            return SetupCheckAllToAllvcAllGatherGmm(inTensorDescs, outTensorDescs.at(0));
526	        default:
527	            ATB_LOG(ERROR) << GetLogPrefix() << "not support type:" << param_.type;
528	            return ERROR_INVALID_PARAM;
529	    }
530	}
531	
532	Status LinearParallelOperation::SetupCheckLinearAllReduce(const SVector<TensorDesc> &inTensorDescs,
533	                                                          const TensorDesc &outTensorDesc) const
534	{
535	    if (inTensorDescs.at(0).dtype == ACL_INT8 &&
536	        param_.quantType == atb::infer::LinearParallelParam::QuantType::QUANT_TYPE_PER_GROUP) {
537	        ATB_LOG(ERROR) << GetLogPrefix() << "In the W8A8 scenario, per_group is not supported.";
538	        return ERROR_INVALID_PARAM;
539	    }
540	    if (!OperationUtil::MatmulInTensorDescsCheck(inTensorDescs, GetLogPrefix(), commonCheckParam_)) {
541	        return ERROR_INVALID_TENSOR_DIM;
542	    }
543	    return OperationUtil::MatmulOutTensorCheck(outTensorDesc, inTensorDescs, GetLogPrefix(), commonCheckParam_) ?
544	               NO_ERROR :
545	               ERROR_INVALID_TENSOR_DIM;
546	}
547	
548	Status LinearParallelOperation::SetupCheckLinearReduceScatter(const SVector<TensorDesc> &inTensorDescs,
549	                                                              TensorDesc &outTensorDesc) const
550	{
551	    if (InferShapeCheckLinearReduceScatter(inTensorDescs) != NO_ERROR) {
552	        return ERROR_INVALID_TENSOR_DIM;
553	    }
554	    if (param_.outDataType != ACL_DT_UNDEFINED && outTensorDesc.dtype != param_.outDataType) {
555	        return ERROR_INVALID_TENSOR_INI_MATCH;
556	    }
557	    if (inTensorDescs.at(0).shape.dims[0] == 1) {
558	        outTensorDesc.shape.dims[1] *= param_.rankSize;
559	    } else {
560	        outTensorDesc.shape.dims[0] *= param_.rankSize;
561	    }
562	    return OperationUtil::MatmulOutTensorCheck(outTensorDesc, inTensorDescs, GetLogPrefix(), commonCheckParam_) ?
563	               NO_ERROR :
564	               ERROR_INVALID_TENSOR_DIM;
565	}
566	
567	Status LinearParallelOperation::SetupCheckAllGatherLinear(SVector<TensorDesc> &inTensorDescs,
568	                                                          const SVector<TensorDesc> &outTensorDescs) const
569	{
570	    if (InferShapeCheckAllGatherLinear(inTensorDescs) != NO_ERROR) {
571	        return ERROR_INVALID_TENSOR_DIM;
572	    }
573	    if (param_.outDataType != ACL_DT_UNDEFINED && outTensorDescs.at(0).dtype != param_.outDataType) {
574	        return ERROR_INVALID_TENSOR_INI_MATCH;
575	    }
576	    inTensorDescs.at(0).shape.dims[0] *= param_.rankSize;
577	    if (!OperationUtil::MatmulOutTensorCheck(outTensorDescs.at(0), inTensorDescs, GetLogPrefix(), commonCheckParam_)) {
578	        return ERROR_INVALID_TENSOR_DIM;
579	    }
580	    if (outTensorDescs.size() == OUT_TENSOR_NUM_WITH_MID) {
581	        if (outTensorDescs.at(1).shape.dims[0] != inTensorDescs.at(0).shape.dims[0]) {
582	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor1 dim0 does not match (rankSize * inTensor0 dim0)";
583	        }
584	    }
585	    return NO_ERROR;
586	}
587	
588	Status LinearParallelOperation::SetupCheckAllGatherLinearReduceScatter(SVector<TensorDesc> &inTensorDescs,
589	                                                                       TensorDesc &outTensorDesc) const
590	{
591	    if (InferShapeCheckAllGatherLinearReduceScatter(inTensorDescs) != NO_ERROR) {
592	        return ERROR_INVALID_TENSOR_DIM;
593	    }
594	    inTensorDescs.at(0).shape.dims[0] *= param_.twoDimTPInfo.agDim;
595	    outTensorDesc.shape.dims[0] *= param_.twoDimTPInfo.rsDim;
596	    return OperationUtil::MatmulOutTensorCheck(outTensorDesc, inTensorDescs, GetLogPrefix(), commonCheckParam_) ?
597	               NO_ERROR :
598	               ERROR_INVALID_TENSOR_DIM;
599	}
600	
601	Status LinearParallelOperation::SetupCheckAllToAllvcAllGatherGmm(const SVector<TensorDesc> &inTensorDescs,
602	                                                                 const TensorDesc &outTensorDesc) const
603	{
604	    if (InferShapeCheckAllToAllvcAllGatherGmm(inTensorDescs) != NO_ERROR) {
605	        return ERROR_INVALID_TENSOR_DIM;
606	    }
607	    return AllToAllvcAllGatherGmmOutTensorCheck(inTensorDescs, outTensorDesc, GetLogPrefix()) ?
608	               NO_ERROR :
609	               ERROR_INVALID_TENSOR_DIM;
610	}
611	
612	nlohmann::json LinearParallelOperation::GetParamJson() const
613	{
614	    return OpParamToJson(param_);
615	}
616	
617	std::shared_ptr<Runner> LinearParallelOperation::CreateRunner(Context &context) const
618	{
619	    ContextBase *contextBase = dynamic_cast<ContextBase *>(&context);
620	    if (!contextBase) {
621	        ATB_LOG(DEBUG) << "context cast to contextBase failed!";
622	        return nullptr;
623	    }
624	    if (param_.backend == "hccl" || param_.backend == "lccl") {
625	        return std::make_shared<LinearParallelGraphRunner>(param_, *contextBase);
626	    } else if (param_.backend == "lcoc") {
627	        return std::make_shared<LinearParallelLcocRunner>(param_, context);
628	    } else if (param_.backend == "mc2") {
629	        if (param_.hcclComm == nullptr) {
630	            return std::make_shared<LinearParallelAclnnRunner>(param_, !param_.rankTableFile.empty());
631	        } else {
632	            return std::make_shared<LinearParallelAclnnRunner>(param_, param_.hcclComm);
633	        }
634	    }
635	    return std::shared_ptr<Runner>();
636	}
637	} // namespace atb
