#include "linear_parallel_operation.h"
#include <sstream>
#include "atb/utils/log.h"
#include "atb/utils/config.h"
#include "atb/utils/tensor_check.h"
#include "atb/utils/tensor_util.h"
#include "atb/utils/param_to_json.h"
